sksl:
uniform shader image;
uniform float2 size;
uniform float time;
layout(color) uniform half4 screenColor;
uniform float threshold;
uniform float softness;
uniform float spill;
uniform float blackClip;
uniform float whiteClip;
uniform float feather;
uniform float despill;
uniform float autoSample;
uniform float invert;
float2 chroma(half3 c) { return float2(-0.168736 * c.r - 0.331264 * c.g + 0.5 * c.b, 0.5 * c.r - 0.418688 * c.g - 0.081312 * c.b); }
half4 sampleBackground(float2 coord) {
    if (autoSample < 0.5) return screenColor;
    float2 e = max(size, float2(2.0)) * 0.018;
    return (image.eval(float2(e.x, e.y)) + image.eval(float2(size.x - e.x, e.y)) +
            image.eval(float2(e.x, size.y - e.y)) + image.eval(float2(size.x - e.x, size.y - e.y))) * 0.25;
}
float matteAt(float2 coord, float2 keyChroma) {
    half4 c = image.eval(coord);
    if (c.a <= 0.001) return 0.0;
    float d = distance(chroma(unpremul(c).rgb), keyChroma);
    float keep = smoothstep(threshold, threshold + softness + 0.0001, d);
    return invert > 0.5 ? 1.0 - keep : keep;
}
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    float2 keyChroma = chroma(unpremul(sampleBackground(coord)).rgb);
    float matte = matteAt(coord, keyChroma);
    matte = clamp((matte - blackClip) / max(whiteClip - blackClip, 0.0001), 0.0, 1.0);
    if (feather > 0.01) {
        float radius = max(feather, 0.0);
        float sum = matte;
        float2 ax = float2(radius, 0.0);
        float2 ay = float2(0.0, radius);
        float2 ad = float2(radius * 0.7071, radius * 0.7071);
        sum += matteAt(coord + ax, keyChroma);
        sum += matteAt(coord - ax, keyChroma);
        sum += matteAt(coord + ay, keyChroma);
        sum += matteAt(coord - ay, keyChroma);
        sum += matteAt(coord + ad, keyChroma);
        sum += matteAt(coord - ad, keyChroma);
        sum += matteAt(coord + float2(ad.x, -ad.y), keyChroma);
        sum += matteAt(coord - float2(ad.x, -ad.y), keyChroma);
        matte = mix(matte, sum / 9.0, clamp(feather / 12.0, 0.0, 1.0));
    }
    float3 rgb = unpremul(c).rgb;
    float3 key = unpremul(sampleBackground(coord)).rgb;
    float keyLen = max(dot(key, key), 0.0001);
    float along = dot(rgb, key) / keyLen;
    float neutral = dot(rgb, float3(0.2126, 0.7152, 0.0722));
    float excess = max(along - neutral, 0.0);
    float3 despilled = clamp(rgb - key * excess * despill * spill, 0.0, 1.0);
    rgb = mix(rgb, despilled, clamp(spill + despill, 0.0, 1.0));
    return half4(rgb * matte, c.a * matte);
}
